script.setup:
// planck.js (a Box2D port) simulates a rope bridge, a swinging chain and falling shapes;
// the scene turns every fixture into triangles each frame. Drag a body with the mouse.
const mod = await ctx.utils.import("https://esm.sh/planck@1.5.0");
const P = mod.default ?? mod;
const [w0, h0] = ctx.resolution;
const H = 20, W = H * w0 / h0;
const world = new P.World({ gravity: { x: 0, y: -10 } });
const color = new Map();
const ground = world.createBody();
const box = (body, hx, hy, center, rgb, fix = {}) => { const f = body.createFixture(new P.Box(hx, hy, center ?? { x: 0, y: 0 }, 0), { density: 1, friction: 0.6, ...fix }); color.set(f, rgb); return f; };
const stone = [0.22, 0.24, 0.3];
box(ground, W, 0.6, { x: 0, y: -0.6 }, stone);
// Walls at the screen edges keep the shapes in view.
for (const x of [-W / 2 - 0.3, W / 2 + 0.3]) box(ground, 0.5, H, { x, y: H / 2 }, stone);
const pillarX = W * 0.17, pillarH = 8;
for (const x of [-pillarX, pillarX + W * 0.18]) box(ground, 0.5, pillarH / 2, { x, y: pillarH / 2 }, stone);
// Rope bridge: planks joined at their ends, hanging between the two pillars.
const left = -pillarX + 0.5, right = pillarX + W * 0.18 - 0.5, planks = 16, plankW = (right - left) / planks;
let prev = ground;
for (let i = 0; i < planks; i++) {
  const plank = world.createDynamicBody({ position: { x: left + plankW * (i + 0.5), y: pillarH - 0.1 } });
  box(plank, plankW * 0.47, 0.2, null, [0.62, 0.42, 0.25], { density: 2 });
  world.createJoint(new P.RevoluteJoint({}, prev, plank, { x: left + plankW * i, y: pillarH - 0.1 }));
  prev = plank;
}
world.createJoint(new P.RevoluteJoint({}, prev, ground, { x: right, y: pillarH - 0.1 }));
// A chain hanging from the ceiling at the left, with a heavy ball, pulled aside to swing.
const anchor = { x: -W * 0.36, y: H - 2.6 }, links = 14, linkL = 0.55;
prev = ground;
for (let i = 0; i < links; i++) {
  const link = world.createDynamicBody({ position: { x: anchor.x + linkL * (i + 0.5), y: anchor.y } });
  box(link, linkL * 0.5, 0.11, null, [0.95, 0.75, 0.3], { density: 1 });
  world.createJoint(new P.RevoluteJoint({}, prev, link, { x: anchor.x + linkL * i, y: anchor.y }));
  prev = link;
}
const ball = world.createDynamicBody({ position: { x: anchor.x + linkL * links + 0.8, y: anchor.y } });
color.set(ball.createFixture(new P.Circle(0.8), { density: 6, friction: 0.4 }), [0.95, 0.35, 0.3]);
world.createJoint(new P.RevoluteJoint({}, prev, ball, { x: anchor.x + linkL * links, y: anchor.y }));
const gl = ctx.gl;
const vao = gl.createVertexArray(), buffer = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 20, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 20, 8);
gl.bindVertexArray(null);
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec3 a_color;
uniform vec2 u_view; out vec3 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position.x / u_view.x * 2.0, (a_position.y + 1.2) / u_view.y * 2.0 - 1.0, 0.0, 1.0); }`,
`#version 300 es
precision highp float; in vec3 v_color; out vec4 outColor;
void main(){ outColor = vec4(v_color, 1.0); }`);
const bg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
void main(){ vec3 c = mix(vec3(0.06, 0.07, 0.1), vec3(0.11, 0.12, 0.17), v_uv.y); outColor = vec4(c, 1.0); }`);
Object.assign(ctx.state, { P, world, ground, color, W, H, vao, buffer, program, bg, dropped: [], spawn: 0, drag: null, moved: false, tris: [], lines: [] });

script.render:
const s = ctx.state, P = s.P, u = ctx.uniforms, gl = ctx.gl;
s.world.setGravity({ x: 0, y: -u.u_gravity });
// Drop a new shape now and then; the oldest go away.
s.spawn -= ctx.dt * u.u_rate;
if (s.spawn <= 0) {
  s.spawn = 1;
  const body = s.world.createDynamicBody({ position: { x: (Math.random() - 0.3) * s.W * 0.6, y: s.H + 1 }, angle: Math.random() * 6.28, angularVelocity: (Math.random() - 0.5) * 4 });
  const kind = Math.floor(Math.random() * 3), size = 0.35 + Math.random() * 0.55, sides = 3 + Math.floor(Math.random() * 4);
  const shape = kind === 0 ? new P.Circle(size) : kind === 1 ? new P.Box(size, size * (0.5 + Math.random() * 0.6))
    : new P.Polygon(Array.from({ length: sides }, (_, i) => ({ x: Math.cos(i / sides * 6.283) * size * 1.2, y: Math.sin(i / sides * 6.283) * size * 1.2 })));
  const palette = [[0.3, 0.75, 1.0], [0.45, 0.9, 0.6], [0.85, 0.5, 1.0], [1.0, 0.55, 0.65], [0.98, 0.85, 0.4]];
  s.color.set(body.createFixture(shape, { density: 1, friction: 0.5, restitution: u.u_bounce }), palette[Math.floor(Math.random() * palette.length)]);
  s.dropped.push(body);
  if (s.dropped.length > 70) { const old = s.dropped.shift(); if (s.drag?.getBodyB() === old) { s.world.destroyJoint(s.drag); s.drag = null; } s.world.destroyBody(old); }
}
// Drag a body with the mouse (a MouseJoint pulls it toward the pointer).
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const [w, h] = ctx.resolution, viewW = s.H * w / h;
const target = { x: (ctx.mouse[0] - 0.5) * viewW, y: (1 - ctx.mouse[1]) * s.H - 1.2 };
if (s.moved && ctx.mouseDown && !s.drag) {
  let hit = null;
  s.world.queryAABB(new P.AABB({ x: target.x - 0.01, y: target.y - 0.01 }, { x: target.x + 0.01, y: target.y + 0.01 }), (f) => {
    if (f.getBody().isDynamic() && f.testPoint(target)) { hit = f.getBody(); return false; }
    return true;
  });
  if (hit) s.drag = s.world.createJoint(new P.MouseJoint({ maxForce: 1500 * hit.getMass() }, s.ground, hit, target));
}
if (s.drag) { if (ctx.mouseDown) s.drag.setTarget(target); else { s.world.destroyJoint(s.drag); s.drag = null; } }
s.world.step(Math.min(ctx.dt, 1 / 30), 8, 3);
// Every fixture becomes triangles (filled) plus a darker rim.
const out = s.tris; out.length = 0;
const tri = (a, b, c, col) => out.push(a.x, a.y, ...col, b.x, b.y, ...col, c.x, c.y, ...col);
for (let b = s.world.getBodyList(); b; b = b.getNext()) {
  for (let f = b.getFixtureList(); f; f = f.getNext()) {
    const shape = f.getShape(), col = s.color.get(f) ?? [0.6, 0.6, 0.6];
    const dark = col.map((c) => c * 0.45), lit = b === s.drag?.getBodyB() ? col.map((c) => Math.min(1, c * 1.35)) : col;
    let pts;
    if (shape.getType() === "circle") {
      const c = shape.getCenter(), r = shape.getRadius();
      pts = Array.from({ length: 24 }, (_, i) => b.getWorldPoint({ x: c.x + Math.cos(i / 24 * 6.283) * r, y: c.y + Math.sin(i / 24 * 6.283) * r }));
    } else if (shape.getType() === "polygon") pts = shape.m_vertices.map((v) => b.getWorldPoint(v));
    else continue;
    const center = pts.reduce((m, p) => ({ x: m.x + p.x / pts.length, y: m.y + p.y / pts.length }), { x: 0, y: 0 });
    // Rim: the full shape in a darker shade, then the inset shape on top.
    const inset = Math.min(0.07, 0.3 * Math.min(...pts.map((p) => Math.hypot(p.x - center.x, p.y - center.y))));
    const inner = pts.map((p) => { const d = Math.hypot(p.x - center.x, p.y - center.y) || 1; return { x: p.x + (center.x - p.x) * inset / d, y: p.y + (center.y - p.y) * inset / d }; });
    for (let i = 0; i < pts.length; i++) tri(center, pts[i], pts[(i + 1) % pts.length], dark);
    for (let i = 0; i < inner.length; i++) tri(center, inner[i], inner[(i + 1) % inner.length], lit);
    // A spoke on circles shows them rolling.
    if (shape.getType() === "circle") { const e = inner[0], n = { x: (e.y - center.y) * 0.12, y: -(e.x - center.x) * 0.12 }; tri({ x: center.x + n.x, y: center.y + n.y }, { x: center.x - n.x, y: center.y - n.y }, e, dark); }
  }
}
const j = s.drag;
if (j) { const a = j.getAnchorB(), t = target, n = { x: -(t.y - a.y), y: t.x - a.x }, l = Math.hypot(n.x, n.y) || 1; const k = 0.04 / l; tri({ x: a.x + n.x * k, y: a.y + n.y * k }, { x: a.x - n.x * k, y: a.y - n.y * k }, t, [1, 1, 1]); }
gl.useProgram(s.bg); ctx.utils.drawFullscreen(s.bg);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_view: [viewW, s.H] });
gl.bindVertexArray(s.vao); gl.bindBuffer(gl.ARRAY_BUFFER, s.buffer);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(out), gl.DYNAMIC_DRAW);
gl.drawArrays(gl.TRIANGLES, 0, out.length / 5);
gl.bindVertexArray(null);
ctx.publish("bodies", s.world.getBodyCount());
ctx.publish("joints", s.world.getJointCount());
